# AUTO-GENERATED by Claude Code
# Purpose: e2e test that the page draws its mono font and icons from the copy bundled in
#          services/ui/assets/nerd_fonts/ (so a fresh clone needs no font installed), not
#          from an installed JetBrainsMono Nerd Font.
# Usage: ds test e2e -k e2e_fonts   (needs the app running; see conftest.py)
# ---------------------------------------------------------------------------
from __future__ import annotations

from typing import TYPE_CHECKING

import pytest

if TYPE_CHECKING:
    from tests.services.ui.e2e.conftest import App


@pytest.mark.smoke
def test_the_bundled_mono_font_is_the_one_loaded(app: App) -> None:
    # an @font-face face is in document.fonts; "loaded" means the page fetched and uses it
    faces = app.page.evaluate(
        """async () => { await document.fonts.ready;
             return [...document.fonts].filter(f => f.family.replace(/"/g, '') === 'JetBrainsMono Nerd Font')
                                       .map(f => [f.weight, f.status]); }"""
    )
    assert ["400", "loaded"] in faces
    assert any(weight == "700" for weight, _ in faces)
